<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';

type Status = 'pending' | 'generating' | 'review' | 'approved';
interface Frame { active: number; status: Status; shown: number }

// The hero demo replays one spec going through the three phases, each
// generated by a different provider — the two things Caramelo is about.
const phases = [
  {
    name: 'Requirements', file: 'spec.md', model: 'Claude',
    lines: [
      '# Feature: Password reset',
      '## User stories',
      '- As a user, I can request a reset link by email.',
      '## Requirements',
      '- FR-001: The link expires after 30 minutes.',
      '- FR-002: A used link cannot be reused.',
    ],
  },
  {
    name: 'Design', file: 'plan.md', model: 'GitHub Copilot',
    lines: [
      '# Plan: Password reset',
      '## Technical context',
      '- Node 22 · Express · PostgreSQL',
      '## Data model (data-model.md)',
      '- reset_tokens(user_id, token_hash, expires_at)',
      '- Store only the hash of each token.',
    ],
  },
  {
    name: 'Tasks', file: 'tasks.md', model: 'Ollama (local)',
    lines: [
      '## Phase 1: Setup',
      '- [ ] T001 Create the reset_tokens migration',
      '- [ ] T002 [P] Add the token hashing helper',
      '## Phase 2: User story 1',
      '- [ ] T003 POST /password/reset sends the link',
      '- [ ] T004 Reject expired or used tokens',
    ],
  },
];

const frames: Frame[] = [];
phases.forEach((p, i) => {
  for (let k = 1; k <= p.lines.length; k++) frames.push({ active: i, status: 'generating', shown: k });
  for (let n = 0; n < 4; n++) frames.push({ active: i, status: 'review', shown: p.lines.length });
  for (let n = 0; n < 2; n++) frames.push({ active: i, status: 'approved', shown: p.lines.length });
});
for (let n = 0; n < 4; n++) frames.push(frames[frames.length - 1]);

const STILL: Frame = { active: 1, status: 'review', shown: phases[1].lines.length };
const frame = ref<Frame>(STILL);
let timer: ReturnType<typeof setInterval> | undefined;

onMounted(() => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  let i = 0;
  frame.value = frames[0];
  timer = setInterval(() => {
    i = (i + 1) % frames.length;
    frame.value = frames[i];
  }, 420);
});
onBeforeUnmount(() => clearInterval(timer));

const statusOf = (j: number): Status => {
  const f = frame.value;
  return j < f.active ? 'approved' : j === f.active ? f.status : 'pending';
};
const statusLabel: Record<Status, string> = {
  pending: 'Pending', generating: 'Generating', review: 'Review', approved: 'Approved',
};
const current = computed(() => phases[frame.value.active]);
const visibleLines = computed(() => current.value.lines.slice(0, frame.value.shown));
const lineKind = (line: string) => (line.startsWith('#') ? 'h' : line.startsWith('- [') ? 'task' : 'li');

const installCmd = 'ext install fsilvaortiz.caramelo';
const copied = ref(false);
async function copyInstall() {
  try {
    await navigator.clipboard.writeText(installCmd);
    copied.value = true;
    setTimeout(() => { copied.value = false; }, 1600);
  } catch { /* clipboard unavailable: the command stays visible to select */ }
}

const MARKETPLACE = 'https://marketplace.visualstudio.com/items?itemName=fsilvaortiz.caramelo';

const steps = [
  { name: 'Constitution', file: 'constitution.md', text: 'The principles every generation has to follow. Write them, generate them from a description, or sync them from your organization’s repository.' },
  { name: 'Requirements', file: 'spec.md', text: 'User stories and testable requirements from a one-line brief. Clarify asks up to five questions where the brief is ambiguous.' },
  { name: 'Design', file: 'plan.md', text: 'The technical plan, with research.md, data-model.md and contracts/ next to it.' },
  { name: 'Tasks', file: 'tasks.md', text: 'Numbered tasks in dependency order. Tasks marked [P] can run in parallel.' },
  { name: 'Implement', file: 'your code', text: 'Run one task or all of them. The agent reads your codebase and edits files; every write and shell command waits for your approval.' },
  { name: 'Converge', file: 'tasks.md', text: 'Compares the code with the spec and the plan, and appends the work that is still missing. Existing tasks are never rewritten.' },
];

const providers = ['GitHub Copilot', 'Claude', 'OpenAI', 'Gemini', 'Groq', 'Ollama', 'LM Studio', 'Any OpenAI-compatible endpoint'];

const teamFeatures = [
  { title: 'One constitution for every project', code: 'caramelo.constitution.repository', text: 'Keep your principles in a Git repository. Each project keeps an exact copy, and Caramelo offers to sync when the repository changes.' },
  { title: 'Spec Kit hooks run on their own', code: '.specify/extensions.yml', text: 'Hooks run before and after each step, with the same conditions Spec Kit evaluates. Turn each one on or off from the sidebar.' },
  { title: 'Same files as the Spec Kit CLI', code: 'specs/001-password-reset/', text: 'Caramelo reads and writes the same folders and templates, synced from Spec Kit releases. Switch between the two whenever you want.' },
  { title: 'Specs from Jira issues', code: 'Create Spec from Jira', text: 'Pick a Jira Cloud issue and its title and description become the brief for the requirements.' },
];

const guards = [
  'Every file write and shell command asks for approval first.',
  'The agent can only read and write inside your workspace.',
  'Untrusted workspaces never run the agent, hooks or Git.',
  'API keys stay in VS Code’s secret storage and are redacted from logs.',
];
</script>

<template>
  <div class="cm">
    <section class="cm-hero">
      <div class="cm-hero-copy">
        <p class="cm-eyebrow">VS Code extension · Compatible with GitHub Spec Kit</p>
        <h1 class="cm-h1">Approve the <em>spec</em><br>before the AI writes the&nbsp;code.</h1>
        <p class="cm-lede">
          Caramelo puts Spec Kit’s workflow in a sidebar. Requirements, design and tasks are
          generated by the model you choose, and each one waits for your approval before the next.
        </p>
        <div class="cm-actions">
          <a class="cm-btn cm-btn-primary" :href="MARKETPLACE">Install from the Marketplace</a>
          <a class="cm-btn cm-btn-ghost" href="/guide/getting-started">Read the guide</a>
        </div>
        <div class="cm-install">
          <code>{{ installCmd }}</code>
          <button type="button" @click="copyInstall">{{ copied ? 'Copied' : 'Copy' }}</button>
        </div>
        <p class="cm-fine">Free and open source (MIT) · VS Code 1.95 or later</p>
      </div>

      <div class="cm-demo" role="img"
        aria-label="The Caramelo sidebar taking a password-reset spec through Requirements, Design and Tasks, each phase generated by a different model and approved before the next.">
        <div class="cm-demo-activity" aria-hidden="true">
          <img src="/caramelo-logo.png" alt="" width="26" height="26">
        </div>
        <div class="cm-demo-side" aria-hidden="true">
          <div class="cm-demo-title">Caramelo</div>
          <div class="cm-demo-provider">
            <span class="cm-dot cm-dot-on"></span>
            <span :key="current.model" class="cm-swap">{{ current.model }}</span>
          </div>
          <div class="cm-demo-spec">▾ 001-password-reset</div>
          <ul class="cm-demo-phases">
            <li v-for="(p, j) in phases" :key="p.name" :class="['cm-phase', `is-${statusOf(j)}`]">
              <span class="cm-phase-icon"></span>
              <span class="cm-phase-name">{{ p.name }}</span>
              <span class="cm-phase-status">{{ statusLabel[statusOf(j)] }}</span>
            </li>
          </ul>
        </div>
        <div class="cm-demo-editor" aria-hidden="true">
          <div class="cm-demo-tabs"><span class="cm-demo-tab">{{ current.file }}</span></div>
          <div class="cm-demo-lens">
            <template v-if="frame.status === 'review'"><b>Approve</b> · Regenerate</template>
            <template v-else-if="frame.status === 'approved'"><span class="cm-ok">✓ Approved</span> · Next phase</template>
            <template v-else>Writing with {{ current.model }}…</template>
          </div>
          <div class="cm-demo-doc">
            <div v-for="(line, k) in visibleLines" :key="current.file + k" :class="['cm-line', `cm-line-${lineKind(line)}`]">
              {{ line }}<span v-if="frame.status === 'generating' && k === visibleLines.length - 1" class="cm-caret"></span>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="cm-section">
      <h2 class="cm-h2">One phase at a time</h2>
      <p class="cm-sub">
        Each step writes a file you can read, edit and commit. Approving one unlocks the next;
        regenerating one marks the steps after it as out of date.
      </p>
      <ol class="cm-steps">
        <li v-for="s in steps" :key="s.name" class="cm-step">
          <div class="cm-step-head">
            <span class="cm-step-name">{{ s.name }}</span>
            <code class="cm-step-file">{{ s.file }}</code>
          </div>
          <p>{{ s.text }}</p>
        </li>
      </ol>
    </section>

    <section class="cm-section cm-models">
      <div>
        <h2 class="cm-h2">Use the model you already pay for, or one on your laptop</h2>
        <p class="cm-sub">
          Set up several providers and switch between them with a click, even halfway through a
          spec. Custom auth headers work behind corporate gateways.
        </p>
      </div>
      <ul class="cm-chips">
        <li v-for="p in providers" :key="p">{{ p }}</li>
      </ul>
    </section>

    <section class="cm-section">
      <h2 class="cm-h2">Works the way your team already does</h2>
      <div class="cm-grid">
        <article v-for="f in teamFeatures" :key="f.title" class="cm-card">
          <h3>{{ f.title }}</h3>
          <p>{{ f.text }}</p>
          <code>{{ f.code }}</code>
        </article>
      </div>
    </section>

    <section class="cm-section cm-guards">
      <h2 class="cm-h2">Nothing changes without you</h2>
      <ul>
        <li v-for="g in guards" :key="g">{{ g }}</li>
      </ul>
    </section>

    <section class="cm-close">
      <img src="/caramelo-logo.png" alt="" width="120" height="120">
      <div>
        <h2 class="cm-h2">Try it on your next feature</h2>
        <div class="cm-actions">
          <a class="cm-btn cm-btn-primary" :href="MARKETPLACE">Install from the Marketplace</a>
          <a class="cm-btn cm-btn-ghost" href="https://github.com/fsilvaortiz/caramelo">View on GitHub</a>
        </div>
      </div>
    </section>
  </div>
</template>

